import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.HashMap;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;int n = Integer.parseInt(line1.trim());StringTokenizer st = new StringTokenizer(br.readLine());HashMap<Integer, Long> counts = new HashMap<Integer, Long>();for (int i = 0; i < n; i++) {int val = Integer.parseInt(st.nextToken());int diff = val - i;counts.put(diff, counts.getOrDefault(diff, 0L) + 1L);}long totalPairs = 0;for (long count : counts.values()) {if (count > 1) {totalPairs += count * (count - 1);}}System.out.println(totalPairs);}}